import { FlaskConical } from 'lucide-react';
import AnimatedNumber from './AnimatedNumber.jsx';
import EmptyState from './EmptyState.jsx';
import { formatMetric } from '../lib/format.js';

// Shown when metrics.json does not list its own limitations. These restate the project plan.
const DEFAULT_LIMITATIONS = [
  "The training and evaluation data is synthetic, generated by the team's own generator.",
  'Results describe how the pipeline behaves on that synthetic data, not on real job listings.',
  'ProofHire gives a risk estimate, not a verification of the employer.',
];

// `metrics` is the normalized object from api/dashboard.js (or null). Missing numbers say "Not available".
export default function MetricsCard({ metrics }) {
  if (!metrics) {
    return (
      <div className="card">
        <h2 className="card__title">Model metrics</h2>
        <EmptyState title="Metrics are not available" message="The metrics file could not be read." />
      </div>
    );
  }

  const limitations = metrics.limitations.length > 0 ? metrics.limitations : DEFAULT_LIMITATIONS;
  const items = [
    { label: 'Precision', value: metrics.precision },
    { label: 'Recall', value: metrics.recall },
    { label: 'F1', value: metrics.f1 },
    { label: 'PR-AUC', value: metrics.prAuc },
  ];

  return (
    <div className="card">
      <div className="card__head">
        <h2 className="card__title">Model metrics</h2>
        <span className="source-badge">
          <FlaskConical size={14} aria-hidden="true" />
          Synthetic benchmark
        </span>
      </div>
      <dl className="metric-grid">
        {items.map((item) => (
          <div key={item.label} className="metric">
            <dt>{item.label}</dt>
            <dd>
              {typeof item.value === 'number' ? (
                <AnimatedNumber value={item.value} format={(n) => n.toFixed(3)} />
              ) : (
                formatMetric(item.value)
              )}
            </dd>
          </div>
        ))}
      </dl>
      <h3 className="card__subtitle">Limitations</h3>
      <ul className="bullet-list">
        {limitations.map((line) => (
          <li key={line}>{line}</li>
        ))}
      </ul>
    </div>
  );
}
